// Port of rankboard/fracindex.py. Must return byte-identical keys: the client
// uses it to predict where the server will put a dropped card, so the card
// does not visibly jump when the server's answer arrives.
// Checked against samples/key_vectors.json (generated by the Python side).

export const DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
const BASE = DIGITS.length;
export const SMALLEST_INTEGER = "A" + "0".repeat(26);

export class KeyError extends Error {}

function idx(c: string): number {
  const i = DIGITS.indexOf(c);
  if (i < 0 || c.length !== 1) throw new KeyError(`bad digit ${JSON.stringify(c)}`);
  return i;
}

function midpoint(a: string, b: string | null): string {
  if (b !== null && a >= b) throw new KeyError(`midpoint: ${a} >= ${b}`);
  if (a.endsWith("0") || (b !== null && b.endsWith("0"))) throw new KeyError("midpoint: trailing zero");
  if (b !== null) {
    let n = 0;
    while ((n < a.length ? a[n] : "0") === b[n]) n++;
    if (n > 0) return b.slice(0, n) + midpoint(a.slice(n), b.slice(n));
  }
  const digitA = a ? idx(a[0]) : 0;
  const digitB = b !== null ? idx(b[0]) : BASE;
  if (digitB - digitA > 1) return DIGITS[Math.floor((digitA + digitB + 1) / 2)];
  if (b !== null && b.length > 1) return b.slice(0, 1);
  return DIGITS[digitA] + midpoint(a.slice(1), null);
}

function integerLength(head: string): number {
  if (head >= "a" && head <= "z") return head.charCodeAt(0) - 97 + 2;
  if (head >= "A" && head <= "Z") return 90 - head.charCodeAt(0) + 2;
  throw new KeyError(`invalid key head ${JSON.stringify(head)}`);
}

function integerPart(key: string): string {
  const n = integerLength(key[0]);
  if (n > key.length) throw new KeyError(`key too short for its head: ${key}`);
  return key.slice(0, n);
}

export function validateKey(key: string): void {
  if (typeof key !== "string" || key.length === 0) throw new KeyError("key must be a non-empty string");
  for (const c of key) idx(c);
  if (key === SMALLEST_INTEGER) throw new KeyError("key is the reserved smallest integer");
  const i = integerPart(key);
  if (key.slice(i.length).endsWith("0")) throw new KeyError(`key fraction ends in 0: ${key}`);
}

function incrementInteger(x: string): string | null {
  const head = x[0];
  const digs = x.slice(1).split("");
  for (let i = digs.length - 1; i >= 0; i--) {
    const d = idx(digs[i]) + 1;
    if (d === BASE) digs[i] = "0";
    else {
      digs[i] = DIGITS[d];
      return head + digs.join("");
    }
  }
  if (head === "Z") return "a0";
  if (head === "z") return null;
  const h = String.fromCharCode(head.charCodeAt(0) + 1);
  if (h > "a") digs.push("0");
  else digs.pop();
  return h + digs.join("");
}

function decrementInteger(x: string): string | null {
  const head = x[0];
  const digs = x.slice(1).split("");
  for (let i = digs.length - 1; i >= 0; i--) {
    const d = idx(digs[i]) - 1;
    if (d === -1) digs[i] = "z";
    else {
      digs[i] = DIGITS[d];
      return head + digs.join("");
    }
  }
  if (head === "a") return "Zz";
  if (head === "A") return null;
  const h = String.fromCharCode(head.charCodeAt(0) - 1);
  if (h < "Z") digs.push("z");
  else digs.pop();
  return h + digs.join("");
}

/** A key k with a < k < b; null means unbounded on that side. */
export function keyBetween(a: string | null, b: string | null): string {
  if (a !== null) validateKey(a);
  if (b !== null) validateKey(b);
  if (a !== null && b !== null && a >= b) throw new KeyError(`keyBetween: ${a} >= ${b}`);
  if (a === null) {
    if (b === null) return "a0";
    const ib = integerPart(b);
    const fb = b.slice(ib.length);
    if (ib === SMALLEST_INTEGER) return ib + midpoint("", fb);
    if (ib < b) return ib;
    const res = decrementInteger(ib);
    if (res === null) throw new KeyError("cannot decrement any further");
    if (res === SMALLEST_INTEGER) return res + midpoint("", null);
    return res;
  }
  const ia = integerPart(a);
  const fa = a.slice(ia.length);
  if (b === null) {
    const next = incrementInteger(ia);
    return next === null ? ia + midpoint(fa, null) : next;
  }
  const ib = integerPart(b);
  const fb = b.slice(ib.length);
  if (ia === ib) return ia + midpoint(fa, fb);
  const next = incrementInteger(ia);
  if (next === null) throw new KeyError("cannot increment any further");
  if (next < b) return next;
  return ia + midpoint(fa, null);
}

export function keysSequence(n: number): string[] {
  const out: string[] = [];
  let prev: string | null = null;
  for (let i = 0; i < n; i++) {
    prev = keyBetween(prev, null);
    out.push(prev);
  }
  return out;
}
